actions.script:
const ids = String(allLayerIds || '').split(',').map(id => id.trim()).filter(id => id)
const checked = new Set([].concat(shownLayers ?? []).flatMap(value => String(value).split(',')).map(id => id.trim()).filter(id => id))
layerVisibility = Object.fromEntries(ids.map(id => [id, checked.has(id)]))

const preferences = found?.preferences || {}
const installation = Array.from(found?.profileOptions || []).find(option => option.profileId === found?.installationProfileId)
profileOptions = [{value: '', label: ec.l10n.localize('The installation\'s') + (installation ? ' (' + installation.profileName + ')' : '')}]
    .concat(Array.from(found?.profileOptions || []).map(option => ({value: option.profileId, label: option.profileName})))
basemapOptions = Array.from(found?.basemapOptions || []).map(option => ({value: option.layerId, label: option.label}))
const config = effective?.config || {}
const layers = Array.from(config.layers || []).concat(Array.from(config.recordLayers || []))
layerOptions = layers.map(layer => ({value: layer.id, label: layer.label || layer.id}))
const extent = Array.isArray(preferences.extent) ? preferences.extent : null
preferenceValues = {profileId: preferences.profileId || '', basemap: preferences.basemap || '', extent: extent ? extent.join(', ') : '',
    units: preferences.units || '', restoreLastView: preferences.restoreLastView ? 'Y' : 'N',
    shownLayers: layers.filter(layer => layer.visible !== false).map(layer => layer.id), allLayerIds: layers.map(layer => layer.id).join(',')}
